Here is the commit message:
fs/ntfs3: terminate the cached volume label after UTF-8
 conversion

ntfs_fill_super() loads the on-disk volume label with utf16s_to_utf8s()
and stores the result in sbi->volume.label. The converted label is later
exposed through ntfs3_label_show() using %s, but utf16s_to_utf8s() only
returns the number of bytes written and does not add a trailing NUL.

If the converted label fills the entire fixed buffer,
ntfs3_label_show() can read past the end of sbi->volume.label while
looking for a terminator.

Terminate the cached label explicitly after a successful conversion and
clamp the exact-full case to the last byte of the buffer.

Fixes: 82cae269cfa9 ("fs/ntfs3: Add initialization of super block")
Signed-off-by: Pengpeng Hou <pengpeng@iscas.ac.cn>
Signed-off-by: Konstantin Komarov <almaz.alexandrovich@paragon-software.com>

Here is the root cause:
The bug occurs because the function `utf16s_to_utf8s()` does not append a NUL terminator after converting the volume label from UTF-16 to UTF-8. The result is stored in `sbi->volume.label` which is a fixed-size buffer. When the converted string exactly fills the buffer (or is truncated to fill it), there is no room for a trailing NUL. Subsequently, `ntfs3_label_show()` uses `%s` to print the label, which reads until a NUL byte. Without a terminator, this can cause a buffer over-read beyond the allocated array, leading to potential information disclosure or crash.

Here is the patch:
  */
 static int ntfs_fill_super(struct super_block *sb, struct fs_context *fc)
 {
 	int err;
 	struct ntfs_sb_info *sbi = sb->s_fs_info;
 	struct block_device *bdev = sb->s_bdev;
 	struct ntfs_mount_options *fc_opts;
 	struct ntfs_mount_options *options = NULL;
 	struct inode *inode;
 	struct ntfs_inode *ni;
 	size_t i, tt, bad_len, bad_frags;
 	CLST vcn, lcn, len;
 	struct ATTRIB *attr;
 	const struct VOLUME_INFO *info;
 	u32 done, bytes;
 	struct ATTR_DEF_ENTRY *t;
 	u16 *shared;
 	struct MFT_REF ref;
 	bool ro = sb_rdonly(sb);
 	struct NTFS_BOOT *boot2 = NULL;

 	ref.high = 0;

 	sbi->sb = sb;
 	fc_opts = fc->fs_private;
 	if (!fc_opts) {
 		errorf(fc, "missing mount options");
 		return -EINVAL;
 	}
 	options = kmemdup(fc_opts, sizeof(*fc_opts), GFP_KERNEL);
 	if (!options)
 		return -ENOMEM;

 	if (fc_opts->nls_name) {
 		options->nls_name = kstrdup(fc_opts->nls_name, GFP_KERNEL);
 		if (!options->nls_name) {
 			kfree(options);
 			return -ENOMEM;
 		}
 	}
 	sbi->options = options;
 	sb->s_flags |= SB_NODIRATIME;
 	sb->s_magic = 0x7366746e; // "ntfs"
 	sb->s_op = &ntfs_sops;
 	sb->s_export_op = &ntfs_export_ops;
 	sb->s_time_gran = NTFS_TIME_GRAN; // 100 nsec
 	sb->s_xattr = ntfs_xattr_handlers;
 	set_default_d_op(sb, options->nocase ? &ntfs_dentry_ops : NULL);

 	options->nls = ntfs_load_nls(options->nls_name);
 	if (IS_ERR(options->nls)) {
 		options->nls = NULL;
 		errorf(fc, "Cannot load nls %s", options->nls_name);
 		err = -EINVAL;
 		goto out;
 	}

 	if (bdev_max_discard_sectors(bdev) && bdev_discard_granularity(bdev)) {
 		sbi->discard_granularity = bdev_discard_granularity(bdev);
 		sbi->discard_granularity_mask_inv =
 			~(u64)(sbi->discard_granularity - 1);
 	}

 	/* Parse boot. */
 	err = ntfs_init_from_boot(sb, bdev_logical_block_size(bdev),
 				  bdev_nr_bytes(bdev), &boot2);
 	if (err)
 		goto out;

 	/*
 	 * Load $Volume. This should be done before $LogFile
 	 * 'cause 'sbi->volume.ni' is used in 'ntfs_set_state'.
 	 */
 	ref.low = cpu_to_le32(MFT_REC_VOL);
 	ref.seq = cpu_to_le16(MFT_REC_VOL);
 	inode = ntfs_iget5(sb, &ref, &NAME_VOLUME);
 	if (IS_ERR(inode)) {
 		err = PTR_ERR(inode);
 		ntfs_err(sb, "Failed to load $Volume (%d).", err);
 		goto out;
 	}

 	ni = ntfs_i(inode);

 	/* Load and save label (not necessary). */
 	attr = ni_find_attr(ni, NULL, NULL, ATTR_LABEL, NULL, 0, NULL, NULL);

 	if (!attr) {
 		/* It is ok if no ATTR_LABEL */
 	} else if (!attr->non_res && !is_attr_ext(attr)) {
 		/* $AttrDef allows labels to be up to 128 symbols. */
 		err = utf16s_to_utf8s(resident_data(attr),
 				      le32_to_cpu(attr->res.data_size) >> 1,
 				      UTF16_LITTLE_ENDIAN, sbi->volume.label,
 				      sizeof(sbi->volume.label));
-		if (err < 0)
+		if (err < 0) {
 			sbi->volume.label[0] = 0;
+		} else if (err >= sizeof(sbi->volume.label)) {
+			sbi->volume.label[sizeof(sbi->volume.label) - 1] = 0;
+		} else {
+			sbi->volume.label[err] = 0;
+		}
 	} else {
 		/* Should we break mounting here? */
 		//err = -EINVAL;
 		//goto put_inode_out;
 	}

 	attr = ni_find_attr(ni, attr, NULL, ATTR_VOL_INFO, NULL, 0, NULL, NULL);
 	if (!attr || is_attr_ext(attr) ||
 	    !(info = resident_data_ex(attr, SIZEOF_ATTRIBUTE_VOLUME_INFO))) {
 		ntfs_err(sb, "$Volume is corrupted.");
 		err = -EINVAL;
 		goto put_inode_out;
 	}

 	sbi->volume.major_ver = info->major_ver;
 	sbi->volume.minor_ver = info->minor_ver;
 	sbi->volume.flags = info->flags;
 	sbi->volume.ni = ni;
 	if (info->flags & VOLUME_FLAG_DIRTY) {
 		sbi->volume.real_dirty = true;
 		ntfs_info(sb, "It is recommended to use chkdsk.");
 	}

 	/* Load $MFTMirr to estimate recs_mirr. */
 	ref.low = cpu_to_le32(MFT_REC_MIRR);
 	ref.seq = cpu_to_le16(MFT_REC_MIRR);
 	inode = ntfs_iget5(sb, &ref, &NAME_MIRROR);
 	if (IS_ERR(inode)) {
 		err = PTR_ERR(inode);
 		ntfs_err(sb, "Failed to load $MFTMirr (%d).", err);
 		goto out;
 	}

 	sbi->mft.recs_mirr = ntfs_up_cluster(sbi, inode->i_size) >>
 			     sbi->record_bits;

 	iput(inode);

 	/* Load LogFile to replay. */
 	ref.low = cpu_to_le32(MFT_REC_LOG);
 	ref.seq = cpu_to_le16(MFT_REC_LOG);
 	inode = ntfs_iget5(sb, &ref, &NAME_LOGFILE);
 	if (IS_ERR(inode)) {
 		err = PTR_ERR(inode);
 		ntfs_err(sb, "Failed to load \x24LogFile (%d).", err);
 		goto out;
 	}

 	ni = ntfs_i(inode);

 	err = ntfs_loadlog_and_replay(ni, sbi);
 	if (err)
 		goto put_inode_out;

 	iput(inode);

 	if ((sbi->flags & NTFS_FLAGS_NEED_REPLAY) && !ro) {
 		ntfs_warn(sb, "failed to replay log file. Can't mount rw!");
 		err = -EINVAL;
 		goto out;
 	}

 	if ((sbi->volume.flags & VOLUME_FLAG_DIRTY) && !ro && !options->force) {
 		ntfs_warn(sb, "volume is dirty and \"force\" flag is not set!");
 		err = -EINVAL;
 		goto out;
 	}

 	/* Load $MFT. */
 	ref.low = cpu_to_le32(MFT_REC_MFT);
 	ref.seq = cpu_to_le16(1);

 	inode = ntfs_iget5(sb, &ref, &NAME_MFT);
 	if (IS_ERR(inode)) {
 		err = PTR_ERR(inode);
 		ntfs_err(sb, "Failed to load $MFT (%d).", err);
 		goto out;
 	}

 	ni = ntfs_i(inode);

 	sbi->mft.used = ni->i_valid >> sbi->record_bits;
 	tt = inode->i_size >> sbi->record_bits;
 	sbi->mft.next_free = MFT_REC_USER;

 	err = ni_load_all_mi(ni);
 	if (err) {
 		ntfs_err(sb, "Failed to load $MFT's subrecords (%d).", err);
 		goto put_inode_out;
 	}

 	/* Merge MFT bitmap runs from extent records loaded by ni_load_all_mi. */
 	{
 		struct ATTRIB *a = NULL;
 		struct ATTR_LIST_ENTRY *le = NULL;

 		while ((a = ni_enum_attr_ex(ni, a, &le, NULL))) {
 			CLST svcn, evcn;
 			u16 roff;

 			if (a->type != ATTR_BITMAP || !a->non_res)
 				continue;

 			svcn = le64_to_cpu(a->nres.svcn);
 			if (!svcn)
 				continue; /* Base record runs already loaded. */

 			evcn = le64_to_cpu(a->nres.evcn);
 			roff = le16_to_cpu(a->nres.run_off);

 			err = run_unpack_ex(&sbi->mft.bitmap.run, sbi,
 					    MFT_REC_MFT, svcn, evcn, svcn,
 					    Add2Ptr(a, roff),
 					    le32_to_cpu(a->size) - roff);
 			if (err < 0) {
 				ntfs_err(sb, "Failed to unpack $MFT bitmap extent (%d).", err);
 				goto put_inode_out;
 			}
 			err = 0;
 		}
 	}

 	err = wnd_init(&sbi->mft.bitmap, sb, tt);
 	if (err)
 		goto put_inode_out;

 	sbi->mft.ni = ni;

 	/* Load $Bitmap. */
 	ref.low = cpu_to_le32(MFT_REC_BITMAP);
 	ref.seq = cpu_to_le16(MFT_REC_BITMAP);
 	inode = ntfs_iget5(sb, &ref, &NAME_BITMAP);
 	if (IS_ERR(inode)) {
 		err = PTR_ERR(inode);
 		ntfs_err(sb, "Failed to load $Bitmap (%d).", err);
 		goto out;
 	}

 #ifndef CONFIG_NTFS3_64BIT_CLUSTER
 	if (inode->i_size >> 32) {
 		err = -EINVAL;
 		goto put_inode_out;
 	}
 #endif

 	/* Check bitmap boundary. */
 	tt = sbi->used.bitmap.nbits;
 	if (inode->i_size < ntfs3_bitmap_size(tt)) {
 		ntfs_err(sb, "$Bitmap is corrupted.");
 		err = -EINVAL;
 		goto put_inode_out;
 	}

 	err = wnd_init(&sbi->used.bitmap, sb, tt);
 	if (err) {
 		ntfs_err(sb, "Failed to initialize $Bitmap (%d).", err);
 		goto put_inode_out;
 	}

 	iput(inode);

 	/* Compute the MFT zone. */
 	err = ntfs_refresh_zone(sbi);
 	if (err) {
 		ntfs_err(sb, "Failed to initialize MFT zone (%d).", err);
 		goto out;
 	}

 	/* Load $BadClus. */
 	ref.low = cpu_to_le32(MFT_REC_BADCLUST);
 	ref.seq = cpu_to_le16(MFT_REC_BADCLUST);
 	inode = ntfs_iget5(sb, &ref, &NAME_BADCLUS);
 	if (IS_ERR(inode)) {
 		err = PTR_ERR(inode);
 		ntfs_err(sb, "Failed to load $BadClus (%d).", err);
 		goto out;
 	}

 	ni = ntfs_i(inode);
 	bad_len = bad_frags = 0;
 	for (i = 0; run_get_entry(&ni->file.run, i, &vcn, &lcn, &len); i++) {
 		if (lcn == SPARSE_LCN)
 			continue;

 		bad_len += len;
 		bad_frags += 1;
 		if (ro)
 			continue;

 		if (wnd_set_used_safe(&sbi->used.bitmap, lcn, len, &tt) || tt) {
 			/* Bad blocks marked as free in bitmap. */
 			ntfs_set_state(sbi, NTFS_DIRTY_ERROR);
 		}
 	}
 	if (bad_len) {
 		/*
 		 * Notice about bad blocks.
 		 * In normal cases these blocks are marked as used in bitmap.
 		 * And we never allocate space in it.
 		 */
 		ntfs_notice(sb,
 			    "Volume contains %zu bad blocks in %zu fragments.",
 			    bad_len, bad_frags);
 	}
 	iput(inode);

 	/* Load $AttrDef. */
 	ref.low = cpu_to_le32(MFT_REC_ATTR);
 	ref.seq = cpu_to_le16(MFT_REC_ATTR);
 	inode = ntfs_iget5(sb, &ref, &NAME_ATTRDEF);
 	if (IS_ERR(inode)) {
 		err = PTR_ERR(inode);
 		ntfs_err(sb, "Failed to load $AttrDef (%d)", err);
 		goto out;
 	}

 	/*
 	 * Typical $AttrDef contains up to 20 entries.
 	 * Check for extremely large/small size.
 	 */
 	if (inode->i_size < sizeof(struct ATTR_DEF_ENTRY) ||
 	    inode->i_size > 100 * sizeof(struct ATTR_DEF_ENTRY)) {
 		ntfs_err(sb, "Looks like $AttrDef is corrupted (size=%llu).",
 			 inode->i_size);
 		err = -EINVAL;
 		goto put_inode_out;
 	}

 	bytes = inode->i_size;
 	sbi->def_table = t = kvmalloc(bytes, GFP_KERNEL);
 	if (!t) {
 		err = -ENOMEM;
 		goto put_inode_out;
 	}

 	/* Read the entire file. */
 	err = inode_read_data(inode, sbi->def_table, bytes);
 	if (err) {
 		ntfs_err(sb, "Failed to read $AttrDef (%d).", err);
 		goto put_inode_out;
 	}

 	if (ATTR_STD != t->type) {
 		ntfs_err(sb, "$AttrDef is corrupted.");
 		err = -EINVAL;
 		goto put_inode_out;
 	}

 	t += 1;
 	sbi->def_entries = 1;
 	done = sizeof(struct ATTR_DEF_ENTRY);

 	while (done + sizeof(struct ATTR_DEF_ENTRY) <= bytes) {
 		u32 t32 = le32_to_cpu(t->type);
 		u64 sz = le64_to_cpu(t->max_sz);

 		if ((t32 & 0xF) || le32_to_cpu(t[-1].type) >= t32)
 			break;

 		if (t->type == ATTR_REPARSE)
 			sbi->reparse.max_size = sz;
 		else if (t->type == ATTR_EA)
 			sbi->ea_max_size = sz;

 		done += sizeof(struct ATTR_DEF_ENTRY);
 		t += 1;
 		sbi->def_entries += 1;
 	}
 	iput(inode);

 	/* Load $UpCase. */
 	ref.low = cpu_to_le32(MFT_REC_UPCASE);
 	ref.seq = cpu_to_le16(MFT_REC_UPCASE);
 	inode = ntfs_iget5(sb, &ref, &NAME_UPCASE);
 	if (IS_ERR(inode)) {
 		err = PTR_ERR(inode);
 		ntfs_err(sb, "Failed to load $UpCase (%d).", err);
 		goto out;
 	}

 	if (inode->i_size != 0x10000 * sizeof(short)) {
 		err = -EINVAL;
 		ntfs_err(sb, "$UpCase is corrupted.");
 		goto put_inode_out;
 	}

 	/* Read the entire file. */
 	err = inode_read_data(inode, sbi->upcase, 0x10000 * sizeof(short));
 	if (err) {
 		ntfs_err(sb, "Failed to read $UpCase (%d).", err);
 		goto put_inode_out;
 	}

 #ifdef __BIG_ENDIAN
 	{
 		u16 *dst = sbi->upcase;

 		for (i = 0; i < 0x10000; i++)
 			__swab16s(dst++);
 	}
 #endif

 	shared = ntfs_set_shared(sbi->upcase, 0x10000 * sizeof(short));
 	if (shared && sbi->upcase != shared) {
 		kvfree(sbi->upcase);
 		sbi->upcase = shared;
 	}

 	iput(inode);

 	if (is_ntfs3(sbi)) {
 		/* Load $Secure. */
 		err = ntfs_security_init(sbi);
 		if (err) {
 			ntfs_err(sb, "Failed to initialize $Secure (%d).", err);
 			goto out;
 		}

 		/* Load $Extend. */
 		err = ntfs_extend_init(sbi);
 		if (err) {
 			ntfs_warn(sb, "Failed to initialize $Extend.");
 			goto load_root;
 		}

 		/* Load $Extend/$Reparse. */
 		err = ntfs_reparse_init(sbi);
 		if (err) {
 			ntfs_warn(sb, "Failed to initialize $Extend/$Reparse.");
 			goto load_root;
 		}

 		/* Load $Extend/$ObjId. */
 		err = ntfs_objid_init(sbi);
 		if (err) {
 			ntfs_warn(sb, "Failed to initialize $Extend/$ObjId.");
 			goto load_root;
 		}
 	}

 load_root:
 	/* Load root. */
 	ref.low = cpu_to_le32(MFT_REC_ROOT);
 	ref.seq = cpu_to_le16(MFT_REC_ROOT);
 	inode = ntfs_iget5(sb, &ref, &NAME_ROOT);
 	if (IS_ERR(inode)) {
 		err = PTR_ERR(inode);
 		ntfs_err(sb, "Failed to load root (%d).", err);
 		goto out;
 	}

 	/*
 	 * Final check. Looks like this case should never occurs.
 	 */
 	if (!inode->i_op) {
 		err = -EINVAL;
 		ntfs_err(sb, "Failed to load root (%d).", err);
 		goto put_inode_out;
 	}

 	sb->s_root = d_make_root(inode);
 	if (!sb->s_root) {
 		err = -ENOMEM;
 		goto out;
 	}

 	if (boot2) {
 		/*
 	 	 * Alternative boot is ok but primary is not ok.
 	 	 * Volume is recognized as NTFS. Update primary boot.
 		 */
 		struct buffer_head *bh0 = sb_getblk(sb, 0);
 		if (bh0) {
 			wait_on_buffer(bh0);
 			lock_buffer(bh0);
 			memcpy(bh0->b_data, boot2, sizeof(*boot2));
 			set_buffer_uptodate(bh0);
 			mark_buffer_dirty(bh0);
 			unlock_buffer(bh0);
 			if (!sync_dirty_buffer(bh0))
 				ntfs_warn(sb, "primary boot is updated");
 			put_bh(bh0);
 		}

 		kfree(boot2);
 	}

 	ntfs_create_procdir(sb);

 	if (is_legacy_ntfs(sb))
 		sb->s_flags |= SB_RDONLY;
 	return 0;

 put_inode_out:
 	iput(inode);
 out:
 	/* sbi->options == options */
 	if (options) {
 		put_mount_options(sbi->options);
 		sbi->options = NULL;
 	}

 	ntfs3_put_sbi(sbi);
 	kfree(boot2);
 	return err;
 }



